#ifdef POINTING_DEVICE_ENABLE
/* =================================================================================================
 * Azoteq TPS65 trackpad (QMK driver azoteq_iqs5xx, shares I2C1 GP2/GP3 with the OLED)
 *
 * Where it runs: matrix_scan_user(). QMK calls it from matrix_task() (quantum/matrix.c
 * matrix_scan() -> matrix_scan_kb() -> matrix_scan_user()), i.e. in the same main-loop pass as,
 * but BEFORE, pointing_device_task() (quantum/keyboard.c keyboard_task()). Both the hot-plug check
 * and the tap-latch workaround depend on acting just before the driver's next read of the pad.
 * (With POINTING_DEVICE_MOTION_PIN, pointing_device_task() sends a report on EVERY pass but reads
 * the pad only while RDY is high, so code that ran after it, e.g. in housekeeping_task_user(),
 * would release a held button between two reads and use up the RDY window before checking it.)
 *
 * 1. CPI: re-applied in pointing_device_init_user(), which QMK calls at the end of every
 *    pointing_device_init(). Guarded by POINTING_DEVICE_ENABLE (cost_crafter40 guards its CPI code
 *    with POINTING_DEVICE_DRIVER, which is never defined for keymap code, so it never compiles).
 *
 * 2. Hot-plug: QMK initialises pointing devices only at boot. If that fails the status stays
 *    POINTING_DEVICE_STATUS_INIT_FAILED and pointing_device_task() never polls again
 *    (quantum/pointing_device/pointing_device.c, pointing_device_init / pointing_device_task).
 *    trackpad_hotplug_task() runs at most once per TRACKPAD_HOTPLUG_INTERVAL_MS:
 *      - pad not running: probe 0x74. An absent pad NACKs its address immediately (two attempts,
 *        well under 1 ms), so the matrix scan is not held up. When the pad answers twice in a row
 *        (TRACKPAD_HOTPLUG_SETTLE_MS apart, the connector may still be mating) pointing_device_init()
 *        is called again: driver init (~111 ms, once per plug-in) + pointing_device_init_user().
 *      - pad running: read System Info 0 (0x000F). No answer -> unplugged: stop polling, release any
 *        pad button. SHOW_RESET (bit 7) set -> the pad was power-cycled (re-plugged between two
 *        checks) or its watchdog fired and lost the QMK settings -> re-initialise. The flag is
 *        acknowledged (System Control 0, 0x0431, bit 7 ACK_RESET) after every init.
 *        A failed (re)init releases any pad button too, like an unplug.
 *        The read waits (at most TRACKPAD_ALIGN_MAX_WAIT_MS) for the pad's communication window:
 *        RDY high with POINTING_DEVICE_MOTION_PIN, otherwise one report period after the driver's
 *        last poll. It reads inside the window and leaves the window open; the driver's poll in the
 *        same or the next pass reads that cycle's data and closes it. So the check adds no clock
 *        stretching and loses no report cycle (no tap). Only if no window is seen in time (RDY
 *        wire broken, pad stalled) is a forced read done: the pad stretches SCL until its next
 *        window (<= one report period), and that window is also left open for the driver.
 *
 * 3. Tap latch (QMK >= 0.34.0, commit 0d401d1182 "Preserve Azoteq mouse buttons"): the driver now
 *    starts every report from the buttons of the previous report and only ever SETS bits, and
 *    pointing_device_send() keeps the buttons in the report it feeds back, so a tap's BUTTON1 is
 *    never released (see README.md). Workaround: pointing_device_task_user() records the
 *    buttons that no key holds (= produced by the pad), and matrix_scan_user() removes them from
 *    the pointing device report just before the driver reads the pad again: when RDY is high with
 *    POINTING_DEVICE_MOTION_PIN; without it at once, because the driver's 11 ms throttle returns
 *    before sending anything until that read. The pad re-asserts a held gesture (press-and-hold) on
 *    every read, so the host sees one press and one release; a tap is released one report later.
 *    Until that read, a report sent by an MS_BTNx key (pointing_device_keycode_handler() below)
 *    still carries the removed buttons, so a key does not release a drag on the host.
 *    Keyboard mouse buttons (mousekey) are never touched. Harmless on older QMK, where the driver
 *    ignores incoming buttons.
 *    Known limit: when one driver read fails (I2C error) during a press-and-hold, the driver
 *    returns only the incoming buttons, so the button is released for one read and pressed again
 *    at the next good read - the same as on QMK < 0.34.0, whose driver started from an empty report.
 * ================================================================================================= */
#    include "i2c_master.h"
#    include "timer.h"
#    include "wait.h"
#    include "gpio.h"
#    ifdef MOUSEKEY_ENABLE
#        include "mousekey.h"
#    endif

#    ifndef TRACKPAD_CPI
#        define TRACKPAD_CPI 500 // 0 = keep the pad's native resolution (~1200 CPI)
#    endif
#    ifndef TRACKPAD_HOTPLUG_INTERVAL_MS
#        define TRACKPAD_HOTPLUG_INTERVAL_MS 1000 // presence / reset check period
#    endif
#    ifndef TRACKPAD_HOTPLUG_SETTLE_MS
#        define TRACKPAD_HOTPLUG_SETTLE_MS 250 // re-check a newly seen pad once before the ~111 ms init
#    endif
#    ifndef TRACKPAD_HOTPLUG_RETRY_MS
#        define TRACKPAD_HOTPLUG_RETRY_MS 5000 // back-off after a failed init of a pad that answers
#    endif
#    ifndef TRACKPAD_I2C_TIMEOUT_MS
#        define TRACKPAD_I2C_TIMEOUT_MS 12 // > one 10 ms report period (IQS5xx clock stretching); a NACK returns at once
#    endif
#    ifndef TRACKPAD_ALIGN_MAX_WAIT_MS
#        define TRACKPAD_ALIGN_MAX_WAIT_MS 50 // give up waiting for an open window and do a forced read
#    endif

#    ifdef AZOTEQ_IQS5XX_ADDRESS
#        define TP_ADDR AZOTEQ_IQS5XX_ADDRESS
#    else
#        define TP_ADDR (0x74 << 1) // driver default; AZOTEQ_IQS5XX_ADDRESS is private to azoteq_iqs5xx.c
#    endif
#    define TP_REG_PRODUCT_NUMBER 0x0000   // 2 bytes, big-endian (IQS5xx-B000 datasheet memory map)
#    define TP_REG_SYSTEM_INFO_0 0x000F    // bit 7 SHOW_RESET (datasheet p.37)
#    define TP_REG_SYSTEM_CONTROL_0 0x0431 // bit 7 ACK_RESET, other bits are no-op when 0 (datasheet p.40)
#    define TP_REG_END_COMMS 0xEEEE        // writing any byte ends the communication window (datasheet 8.7)
#    define TP_SHOW_RESET 0x80
#    define TP_ACK_RESET 0x80

#    ifndef POINTING_DEVICE_MOTION_PIN
static uint32_t tp_last_poll   = 0;     // last pointing_device_task_user() call = last driver poll
#    endif
static uint32_t tp_last_check  = 0;     // last hot-plug check
static uint32_t tp_due_since   = 0;     // when the pending (running-state) check became due
static uint16_t tp_interval    = TRACKPAD_HOTPLUG_INTERVAL_MS;
static bool     tp_candidate   = false; // pad answered once, waiting TRACKPAD_HOTPLUG_SETTLE_MS
static bool     tp_check_due   = false;
static uint8_t  tp_pad_buttons = 0;     // buttons the pad put into the report that was just processed
static uint8_t  tp_released    = 0;     // pad buttons removed from the report, not read again by the driver yet

static bool trackpad_is_active(void) {
    return pointing_device_get_status() == POINTING_DEVICE_STATUS_SUCCESS;
}

static void tp_end_session(void) {
    const uint8_t any = 0;
    i2c_write_register16(TP_ADDR, TP_REG_END_COMMS, &any, 1, TRACKPAD_I2C_TIMEOUT_MS);
}

// Mouse buttons currently held by keys (MS_BTNx keycodes go through mousekey and the pointing
// device keycode handler, quantum/action.c register_mouse()). MOUSEKEY_ENABLE is set by
// keyboards/yakamoz/rules.mk.
static uint8_t tp_keyboard_buttons(void) {
#    ifdef MOUSEKEY_ENABLE
    return mousekey_get_report().buttons;
#    else
    return 0;
#    endif
}

// Remove the given buttons from the report that pointing_device_task() feeds back into the driver.
static void tp_drop_buttons(uint8_t buttons) {
    report_mouse_t report = pointing_device_get_report();
    if (report.buttons & buttons) {
        report.buttons &= (uint8_t)~buttons;
        pointing_device_set_report(report);
    }
}

// The driver no longer reads the pad (unplugged, or its (re)initialisation failed), so
// pointing_device_task() sends no more reports: release every pad button on the host now.
// Buttons held by keys stay pressed.
static void tp_release_pad_buttons(void) {
    tp_drop_buttons((uint8_t)~tp_keyboard_buttons());
    tp_pad_buttons = 0;
    tp_released    = 0;
    pointing_device_send();
}

// Read one register byte. The IQS5xx NACKs the first address while it is in a low-power mode and
// answers a retry >= 150 us later (datasheet 8.8.2). An absent pad NACKs both attempts at once.
static bool tp_read_u8(uint16_t reg, uint8_t *value) {
    if (i2c_read_register16(TP_ADDR, reg, value, 1, TRACKPAD_I2C_TIMEOUT_MS) == I2C_STATUS_SUCCESS) {
        return true;
    }
    wait_us(200);
    return i2c_read_register16(TP_ADDR, reg, value, 1, TRACKPAD_I2C_TIMEOUT_MS) == I2C_STATUS_SUCCESS;
}

// Presence probe while the pad is not running: wake/ping like the driver's own init does, then
// confirm that it is an IQS5xx by its product number.
static bool tp_probe_present(void) {
    if (i2c_ping_address(TP_ADDR, TRACKPAD_I2C_TIMEOUT_MS) != I2C_STATUS_SUCCESS) {
        wait_us(200);
        if (i2c_ping_address(TP_ADDR, TRACKPAD_I2C_TIMEOUT_MS) != I2C_STATUS_SUCCESS) {
            return false; // absent: two NACKed address bytes
        }
    }
    uint8_t      product[2] = {0, 0};
    i2c_status_t status     = i2c_read_register16(TP_ADDR, TP_REG_PRODUCT_NUMBER, product, sizeof(product), TRACKPAD_I2C_TIMEOUT_MS);
    tp_end_session();
    if (status != I2C_STATUS_SUCCESS) {
        return false;
    }
    const uint16_t number = ((uint16_t)product[0] << 8) | product[1];
    return number == AZOTEQ_IQS550 || number == AZOTEQ_IQS572 || number == AZOTEQ_IQS525;
}

// True when the pad's communication window is (about to be) open, so that a read does not make
// the pad stretch SCL on the shared bus. Called from matrix_scan_user(), i.e. before the driver's
// read in pointing_device_task() of the same pass has used the window up.
static bool tp_window_open(void) {
#    ifdef POINTING_DEVICE_MOTION_PIN
    return gpio_read_pin(POINTING_DEVICE_MOTION_PIN); // RDY, active high; also the driver's read condition
#    else
    // The driver polls every AZOTEQ_IQS5XX_REPORT_RATE + 1 ms; the window opens one report period
    // after the previous poll ended the session.
    return timer_elapsed32(tp_last_poll) >= AZOTEQ_IQS5XX_REPORT_RATE;
#    endif
}

// (Re)initialise through QMK so that pointing_device_init_user() (CPI, reset ack) runs as well.
static void tp_reinit(void) {
    pointing_device_init(); // blocks ~111 ms: driver soft reset + wait_ms(100) + wait_ms(11)
    if (!trackpad_is_active()) {
        tp_release_pad_buttons(); // init failed (status INIT_FAILED): a held drag would stay pressed
    }
    tp_candidate  = false;
    tp_check_due  = false;
    tp_last_check = timer_read32();
    tp_interval   = trackpad_is_active() ? TRACKPAD_HOTPLUG_INTERVAL_MS : TRACKPAD_HOTPLUG_RETRY_MS;
}

static void trackpad_hotplug_task(void) {
    if (timer_elapsed32(tp_last_check) < tp_interval) {
        return;
    }

    if (!trackpad_is_active()) {
        tp_last_check = timer_read32();
        if (!tp_probe_present()) {
            tp_candidate = false;
            tp_interval  = TRACKPAD_HOTPLUG_INTERVAL_MS;
            return;
        }
        if (!tp_candidate) { // just appeared: confirm once more after the connector has settled
            tp_candidate = true;
            tp_interval  = TRACKPAD_HOTPLUG_SETTLE_MS;
            return;
        }
        tp_reinit();
        return;
    }

    // Running. Wait (a few ms at most) for the pad's communication window.
    if (!tp_check_due) {
        tp_check_due = true;
        tp_due_since = timer_read32();
    }
    const bool aligned = tp_window_open();
    if (!aligned && timer_elapsed32(tp_due_since) < TRACKPAD_ALIGN_MAX_WAIT_MS) {
        return;
    }
    tp_check_due  = false;
    tp_last_check = timer_read32();
    tp_interval   = TRACKPAD_HOTPLUG_INTERVAL_MS;

    uint8_t info0 = 0;
    if (!tp_read_u8(TP_REG_SYSTEM_INFO_0, &info0)) {
        // Unplugged: stop the driver from polling a missing device every 11 ms and make sure no
        // pad button stays pressed on the host (pointing_device_task() no longer sends reports).
        pointing_device_set_status(POINTING_DEVICE_STATUS_FAILED);
        tp_release_pad_buttons();
        return;
    }
    if (info0 & TP_SHOW_RESET) {
        tp_reinit(); // re-plugged or reset since the last check: its configuration is gone
        return;
    }
    // Leave the window open, also after a forced read (which waited for the window to open): the
    // driver's poll in this pass (RDY) or within one report period reads this cycle's data and ends
    // the window. Ending it here would throw that cycle away, and a tap is reported in one cycle only.
}

void pointing_device_init_user(void) {
#    ifdef POINTING_DEVICE_MOTION_PIN
    // pointing_device_init() made RDY a floating input; pull it down so that an unplugged cable
    // reads "no data ready" instead of noise.
    gpio_set_pin_input_low(POINTING_DEVICE_MOTION_PIN);
#    endif
    if (trackpad_is_active()) {
        // The driver's init soft-resets the pad, which sets SHOW_RESET. Acknowledge it so that a
        // later SHOW_RESET means the pad really was power-cycled or reset.
        const uint8_t ack = TP_ACK_RESET;
        i2c_write_register16(TP_ADDR, TP_REG_SYSTEM_CONTROL_0, &ack, 1, TRACKPAD_I2C_TIMEOUT_MS);
#    if TRACKPAD_CPI > 0
        pointing_device_set_cpi(TRACKPAD_CPI); // resolution registers are lost on every reset
#    endif
        tp_end_session();
    }
    tp_last_check = timer_read32();
}

// Called by pointing_device_task() after the driver's get_report (with POINTING_DEVICE_MOTION_PIN
// on every pass, also when RDY was low and the pad was not read).
report_mouse_t pointing_device_task_user(report_mouse_t mouse_report) {
#    ifndef POINTING_DEVICE_MOTION_PIN
    tp_last_poll = timer_read32();
#    endif
#    ifndef TRACKPAD_NO_TAP_LATCH_FIX
    tp_pad_buttons = mouse_report.buttons & (uint8_t)~tp_keyboard_buttons();
    tp_released    = 0; // the driver has read the pad (with RDY it is only set in a pass that reads)
#    endif
    return mouse_report;
}

#    ifndef TRACKPAD_NO_TAP_LATCH_FIX
// True when the report will next be sent only after the driver has read the pad again, so that
// removing the pad's buttons now cannot show up on the host as a release by itself.
static bool tp_driver_reads_next(void) {
#        ifdef POINTING_DEVICE_MOTION_PIN
    // pointing_device_task() reads the pad in this pass only while RDY is high, but sends on every
    // pass: release only right before a read, or a held button is released between two reads.
    return gpio_read_pin(POINTING_DEVICE_MOTION_PIN);
#        else
    // POINTING_DEVICE_TASK_THROTTLE_MS (11 ms, azoteq_iqs5xx.h): pointing_device_task() returns
    // before sending anything until its next poll, which reads the pad first.
    return true;
#        endif
}

// MS_BTNx keys send the report at once (quantum/action.c register_mouse() -> this handler, which
// replaces QMK's weak one in quantum/pointing_device/pointing_device.c with the same logic).
// Between the release in matrix_scan_user() and the driver's next read (up to 11 ms without RDY),
// that report would lack the pad's buttons and the host would see a held drag released and pressed
// again. So it is sent with them, and they are taken out again for the driver right after.
void pointing_device_keycode_handler(uint16_t keycode, bool pressed) {
    if (IS_MOUSEKEY_BUTTON(keycode)) {
        report_mouse_t report = pointing_device_get_report();
        report.buttons        = pointing_device_handle_buttons(report.buttons | tp_released, pressed, keycode - QK_MOUSE_BUTTON_1);
        pointing_device_set_report(report);
        pointing_device_send();
        tp_drop_buttons(tp_released & (uint8_t)~tp_keyboard_buttons());
    }
}
#    endif

// Runs in matrix_task(), i.e. BEFORE pointing_device_task() of the same main-loop pass (see the
// block comment above). The original 'ardakilic' keymap defines no matrix_scan_user().
void matrix_scan_user(void) {
    trackpad_hotplug_task(); // first, so that a window it waited for is also used by the release below
#    ifndef TRACKPAD_NO_TAP_LATCH_FIX
    if (tp_pad_buttons && tp_driver_reads_next()) {
        tp_drop_buttons(tp_pad_buttons); // the driver re-asserts a held gesture in its read
        tp_released    = tp_pad_buttons; // key reports keep them until then (pointing_device_keycode_handler())
        tp_pad_buttons = 0;
    }
#    endif
}
#endif // POINTING_DEVICE_ENABLE


